/**
 * Comment creation, edit window enforcement, mention extraction and soft delete.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, archivePatch, consumeRateLimit
 */
import { emit } from "@/lib/event-bus";
import { resolveMentions } from "@/lib/mentions";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { archivePatch, assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import {
  actorEnvelope,
  commentResource,
  issueResource,
  requireFound,
} from "./_support";
import type {
  CreateCommentInput,
  DeleteCommentInput,
  UpdateCommentInput,
} from "@/schemas/comment";
import type { Comment, CommentThreadNode } from "@/types/comment";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/** How long after posting an author may still edit their own comment. */
const EDIT_WINDOW_MS = 15 * 60 * 1000;

/** How many members are scanned when resolving `@handle` mentions. */
const MENTION_LOOKUP_LIMIT = 100;

/** Token bucket protecting the comment thread from burst posting. */
const COMMENT_CREATE_BUCKET = "comment:create";

/**
 * Posts a comment on a live issue. Mentions written as `@handle` in the body
 * are resolved against the org's members here, so the stored row and the
 * `comment.created` payload agree on who was mentioned — the notification
 * fan-out reads that list rather than re-parsing the markdown.
 */
export async function createComment(
  actor: Actor,
  input: CreateCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "comment:create", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const verdict = await consumeRateLimit(input.orgId, COMMENT_CREATE_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Comment rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const mentionedUserIds = await resolveMentionedUsers(
    input.orgId,
    input.body,
    input.mentionedUserIds,
  );

  const comment = await commentRepo.insertComment(
    { ...input, mentionedUserIds: [...mentionedUserIds] },
    actor.userId,
  );

  await emit("comment.created", {
    ...actorEnvelope(actor),
    commentId: comment.id,
    issueId: comment.issueId,
    mentionedUserIds,
  });

  return comment;
}

/**
 * Edits are allowed inside a fifteen-minute window, or by anyone the role
 * matrix already lets update a comment. `can()` decides the second half —
 * this service only owns the time window.
 */
export async function updateComment(
  actor: Actor,
  input: UpdateCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const comment = requireFound(
    await commentRepo.findCommentById(input.orgId, input.commentId),
    "Comment",
    input.commentId,
  );
  assertCan(actor, "comment:update", commentResource(comment));
  assertNotArchived("Comment", comment.id, comment);

  if (comment.authorId === actor.userId && isPastEditWindow(comment)) {
    throw new Error("The edit window for this comment has closed");
  }

  return commentRepo.updateComment(input);
}

/**
 * Deletion is soft: the row keeps its place so replies below it still have an
 * anchor. `archivePatch()` is what the repository writes; asking for it here
 * documents that this service deliberately never issues a hard delete.
 */
export async function deleteComment(
  actor: Actor,
  input: DeleteCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const comment = requireFound(
    await commentRepo.findCommentById(input.orgId, input.commentId),
    "Comment",
    input.commentId,
  );
  assertCan(actor, "comment:delete", commentResource(comment));
  assertNotArchived("Comment", comment.id, comment);

  const { archivedAt } = archivePatch();
  const archived = await commentRepo.archiveComment(
    input.orgId,
    input.commentId,
  );

  await emit("comment.deleted", {
    ...actorEnvelope(actor),
    occurredAt: archivedAt,
    commentId: archived.id,
    issueId: archived.issueId,
  });

  return archived;
}

export async function getThread(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  return commentRepo.listThread(orgId, issueId);
}

function isPastEditWindow(comment: Comment): boolean {
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. The server list wins on disagreement.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);
  const known = new Set(members.items.map((member) => member.userId));

  return [
    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
  ];
}
/**
 * Explicit project membership for `private` projects.
 */
import { and, eq } from "drizzle-orm";
import { getDb, projectMembers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { OrgId, ProjectId, UserId } from "@/types/common";

export async function listProjectMemberIds(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .select({ userId: projectMembers.userId })
    .from(projectMembers)
    .where(
      and(
        orgPredicate(projectMembers.orgId, orgId),
        eq(projectMembers.projectId, projectId),
      ),
    )
    .all();
  return rows.map((row) => brandId<UserId>(row.userId));
}

/** Idempotent: re-adding an existing member is a no-op, not a conflict. */
export async function addProjectMember(
  orgId: OrgId,
  projectId: ProjectId,
  userId: UserId,
): Promise<void> {
  if (await isProjectMember(orgId, projectId, userId)) return;

  getDb()
    .insert(projectMembers)
    .values({
      orgId,
      projectId,
      userId,
      addedAt: toIsoTimestamp(new Date()),
    })
    .run();
}

export async function removeProjectMember(
  orgId: OrgId,
  projectId: ProjectId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(projectMembers)
    .where(
      and(
        orgPredicate(projectMembers.orgId, orgId),
        eq(projectMembers.projectId, projectId),
        eq(projectMembers.userId, userId),
      ),
    )
    .run();
}

export async function isProjectMember(
  orgId: OrgId,
  projectId: ProjectId,
  userId: UserId,
): Promise<boolean> {
  const row = getDb()
    .select({ userId: projectMembers.userId })
    .from(projectMembers)
    .where(
      and(
        orgPredicate(projectMembers.orgId, orgId),
        eq(projectMembers.projectId, projectId),
        eq(projectMembers.userId, userId),
      ),
    )
    .get();
  return row !== undefined;
}
/**
 * Project rows: cursor listing, slug/key uniqueness, soft delete and restore.
 *
 * Must call (do not reimplement): archivePatch, restorePatch, shouldFilterArchived, uniqueSlug
 */
import { and, count, desc, eq, inArray, isNotNull, like, lt, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import {
  archivePatch,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import { getDb, issues, projects } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toProject } from "./_mappers";
import type {
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { ArchiveScope, OrgId, Page, ProjectId } from "@/types/common";
import type { Project, ProjectStats } from "@/types/project";

export async function findProjectById(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project | null> {
  const row = getDb()
    .select()
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();
  return row ? toProject(row) : null;
}

export async function findProjectBySlug(
  orgId: OrgId,
  slug: string,
): Promise<Project | null> {
  const row = getDb()
    .select()
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.slug, slug)))
    .get();
  return row ? toProject(row) : null;
}

export async function listProjects(
  input: ListProjectsInput,
): Promise<Page<Project>> {
  const db = getDb();
  const sort = { sortColumn: projects.createdAt, idColumn: projects.id };

  // The rows and the total must agree on the archive scope, so normalise the
  // filter's loose `includeArchived` into one `ArchiveScope` up front.
  const scope: ArchiveScope = shouldFilterArchived(input)
    ? {}
    : { includeArchived: true };

  const filters = compact(
    orgPredicate(projects.orgId, input.orgId),
    livePredicate(projects.archivedAt, scope),
    input.status === undefined ? undefined : eq(projects.status, input.status),
    input.query === undefined
      ? undefined
      : like(projects.name, `%${input.query}%`),
  );

  const total = db
    .select({ value: count() })
    .from(projects)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(projects)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(projects.createdAt), desc(projects.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(rows, input.limit, total?.value ?? 0, toProject, (row) => ({
    id: row.id,
    sortValue: row.createdAt,
  }));
}

/** Counts live projects by default; the `projects` quota reads this. */
export async function countProjects(
  orgId: OrgId,
  scope: ArchiveScope = {},
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(projects)
    .where(
      and(
        ...compact(
          orgPredicate(projects.orgId, orgId),
          livePredicate(projects.archivedAt, scope),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertProject(
  input: CreateProjectInput,
): Promise<Project> {
  const taken = await listTakenProjectSlugs(input.orgId);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(projects)
    .values({
      id: newId(),
      orgId: input.orgId,
      name: input.name,
      slug,
      key: input.key,
      description: input.description,
      visibility: input.visibility,
      status: "active",
      leadId: input.leadId,
      color: input.color,
      startsAt: null,
      targetDate: input.targetDate,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toProject(row);
}

export async function updateProject(
  input: UpdateProjectInput,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set({
      ...(input.name === undefined ? {} : { name: input.name }),
      ...(input.description === undefined
        ? {}
        : { description: input.description }),
      ...(input.visibility === undefined
        ? {}
        : { visibility: input.visibility }),
      ...(input.status === undefined ? {} : { status: input.status }),
      ...(input.leadId === undefined ? {} : { leadId: input.leadId }),
      ...(input.color === undefined ? {} : { color: input.color }),
      ...(input.targetDate === undefined
        ? {}
        : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(projects.orgId, input.orgId),
        eq(projects.id, input.projectId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Project ${input.projectId} not found`);
  return toProject(row);
}

export async function archiveProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set(archivePatch())
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .returning()
    .get();

  if (!row) throw new Error(`Project ${projectId} not found`);
  return toProject(row);
}

export async function restoreProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set(restorePatch())
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .returning()
    .get();

  if (!row) throw new Error(`Project ${projectId} not found`);
  return toProject(row);
}

/** Includes archived slugs — a restored project must not collide. */
export async function listTakenProjectSlugs(
  orgId: OrgId,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: projects.slug })
    .from(projects)
    .where(orgPredicate(projects.orgId, orgId))
    .all();
  return rows.map((row) => row.slug);
}

/** Open/closed/overdue counters plus the last write, for the project card. */
export async function getProjectStats(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ProjectStats> {
  const db = getDb();
  const scope = and(
    orgPredicate(issues.orgId, orgId),
    eq(issues.projectId, projectId),
    ...compact(livePredicate(issues.archivedAt, {})),
  );

  const closed = db
    .select({ value: count() })
    .from(issues)
    .where(and(scope, inArray(issues.status, [...CLOSED_ISSUE_STATUSES])))
    .get();

  const all = db.select({ value: count() }).from(issues).where(scope).get();

  const overdue = db
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        scope,
        isNotNull(issues.dueAt),
        lt(issues.dueAt, toIsoTimestamp(new Date())),
      ),
    )
    .get();

  const lastActivity = db
    .select({ value: sql<string | null>`max(${issues.updatedAt})` })
    .from(issues)
    .where(scope)
    .get();

  const closedCount = closed?.value ?? 0;

  return {
    projectId,
    openIssues: (all?.value ?? 0) - closedCount,
    closedIssues: closedCount,
    overdueIssues: overdue?.value ?? 0,
    lastActivityAt:
      lastActivity?.value == null ? null : toIsoTimestamp(lastActivity.value),
  };
}
